-- wave-uluwatu-sanur-2026-10-08: 202 field(s) in one DO block, one UPDATE per column.
-- Each UPDATE must change exactly the number of rows it lists; if one does not, the whole block rolls back.
-- Generated 2026-10-08 by scripts/copy/build-copy-sql.mjs. Guards: md5 of the current text; every literal is ASCII.
do $apply$
declare n int;
begin
  update venues v set why_its_here = d.val
  from (values
    ('360-move-uluwatu', 'd74127cdc0e3bd850c31833d14eb77e6', 'A community-minded gym and training centre in Pecatu, on Jalan Pantai Suluban, with two levels of equipment and an outdoor workout area. Classes cover a lot of ground: strength and conditioning, Hot Pilates, spin, HIIT, Muay Thai and BJJ.'),
    ('ami-studio', '335746d8c0787a9e742a7705c10eb22d', 'Reformer and mat Pilates, plus barre, in an ocean-view studio in Uluwatu. Classes run in small groups and focus on strength, balance and controlled movement.'),
    ('andaz-bali-fitness-centre', 'b1a7a14bd571f21e66a2128228ed284c', 'Andaz Bali in Sanur has no gym of its own, so its guests train next door at the Hyatt Regency. The Shankha Spa fitness centre there is open 24 hours, with about 2,000 sq ft of Precor machines. Free sunrise yoga runs on the beach.'),
    ('aroma-spa-retreat-sanur', '1f7ba69f145c6deded607130b79403bc', 'A day spa in a Sanur garden, with Balinese massage and other treatments. The setting is quiet and the pace unhurried.'),
    ('babi-guling-odah-sanur', 'cc274972f7478508392ba482e6f5fc1b', 'A Balinese roast-pork warung near Pasar Sindhu, with an unusually wide babi guling range. Plates are finished with the house sambal tabia: chili, roasted shrimp paste and lime.'),
    ('bali-barber-sanur-sanur', '17cb27e18eb6ab1dca71521bcb5e5567', 'Bali Barber''s Sanur shop on Jl. Danau Tamblingan, part of a men''s barbershop brand founded in 2012. Cuts, classic hot-towel shaves, beard work and dreadlocks, for all international hair types. It shares the space with The Shampoo Lounge.'),
    ('balique-restaurant', 'ba6cb974615875f42c0dd12e0dffdc08', 'Belgian couple Blaise Samoy and Zohra Boukhari opened this roadside cafe-restaurant in Jimbaran''s fishing village in 2012. Antiques they collected across the archipelago fill a vintage European and colonial interior. The menu is mostly Indonesian, with a multi-dish rijsttafel, plus European and fusion plates.'),
    ('bambu-fitness-bali', 'e6c7c7837e9975293ec0c1285c08694e', 'A large open-plan bamboo gym in the Pecatu and Bingin area. Rogue and Eleiko gear fills zones for Olympic weightlifting, functional fitness and cardio. Group classes include CrossFit and Hyrox, and the site has a cafe plus a sauna and cold plunge for recovery.'),
    ('banana-lounge-bali-uluwatu-bukit', 'f5500e830660d63ca5ed41388a70cbe4', 'A beach club on the Bukit with lounges and sunbeds in a tropical setting. Food and drinks are served, and you book on the venue''s own website.'),
    ('bella-cucina', '4d6a71647ec8420578a1eb4fe40a2447', 'Italian fine dining at the InterContinental Bali Resort in Jimbaran. Handmade pastas and Mediterranean-leaning mains come from an open kitchen into an air-conditioned room lit by chandeliers. Sunday brunch has live music.'),
    ('bluvana-reformer-studio', 'f3cc85c84a533731834ccc56eef261f3', 'Classes at this reformer studio on Jl. Pantai Cemongkak in Pecatu are capped at six reformers. There are eight 50-minute formats, each aimed at a zone or an energy level. Sessions run daily, morning and evening, and you book online.'),
    ('d-nailbar-spa-uluwatu', 'f4a036e4c09b291acc4d76d24e3cca69', 'Near Padang Padang, on Jl. Labuansait, this nail bar does gel, BIAB, extensions and nail art. Lash and brow work is done here too, and it fills up, so book ahead on WhatsApp.'),
    ('fitness-plus', 'a309e0db72a30bd37ecc0c4723a2832f', 'Open 24 hours, this Sanur gym on Bypass Ngurah Rai has modern equipment, locker rooms and a sauna. Local trainers run group classes and personal training.'),
    ('garuda-wisnu-kencana', 'dc0586bfc6347430f60bbdb02f3a921f', 'A cultural park in Ungasan, Badung, built around a giant bronze statue of Vishnu and Garuda. The grounds also hold an amphitheatre and event spaces.'),
    ('genius-cafe', 'e0fd6da3b1a733ffbd8135d179bbad1b', U&'A beachfront cafe and co-working space at Mertasari Beach in south Sanur, open daily 7am\201310pm. The Wi-Fi is fast, the menu is plant-forward all day, and you can sit with your toes in the sand without a beach-club minimum spend.'),
    ('glo-day-spa-salon-sanur-sanur', 'ccdc1bcc0d439f3e59410cf50de5c13d', 'An Australian-owned salon and day spa on Sanur''s main strip. It belongs to the Glo group, which also has branches in Canggu, Seminyak, Echo Beach and Lembongan. It does hair and nails as well as bridal work and massage, all under one roof.'),
    ('gong-restaurant', '8bb56ca3acfc2b973fb522c44dcf3357', U&'Kayumanis Sanur''s Indonesian and Balinese restaurant, on Jl. Tirta Akasa No. 28, open daily 7am\201310pm. The resort setting is intimate and the menu centres on traditional dishes.'),
    ('good-hair-day-sanur', 'fcb5e98f27d328af0e4e80b6112753e1', 'At this hair salon on the Sanur strip, the stylists speak English and do cuts and colour.'),
    ('holiday-inn-bali-sanur-gym', '4c71f7141bbb82524f6a0882b4a21c60', 'Holiday Inn Bali Sanur keeps a small gym on its second floor, open 24 hours to hotel guests only. Inside there''s an upright bike, dumbbells, yoga mats and trainer balls.'),
    ('island-grooming-barbershop', 'f29703f843b1cb83d7f1a66a1c182e63', 'A men''s barbershop for precision cuts, fades and grooming, with shops on Jl. Labuansait in Pecatu and on Jl. Pantai Bingin.'),
    ('karma-spa-at-karma-kandara', 'a729fae900d55d5d900289bdf00e2870', 'Karma Kandara''s clifftop spa in Ungasan, high above the ocean, with a sauna and a saltwater pool. Treatments run from massages and facials to biohacking-style options.'),
    ('ko-japanese-teppanyaki-and-sushi', '67d329bd74039c48caf198bd2bd08295', 'Chef Mitsuaki Senoo runs the Japanese restaurant at the InterContinental Bali Resort in Jimbaran. Teppanyaki is grilled at open counters, there''s a sushi and sashimi bar, and a private tatami room sits inside a Balinese-Japanese interior.'),
    ('koa-shala-sanur', '439c860cbceaa29a8f0a3a48af1d997b', 'A yoga shala and holistic wellness centre in a tropical garden off Jl. Danau Tamblingan. Three open-air yoga classes run every day, plus meditation in the courtyard.'),
    ('koa-shala-spa-sanur', 'b561f1480eca925cda24305fd94d46f6', 'Koa Shala''s spa does Balinese and holistic massage in a quiet courtyard. It sits down a banana-palm-lined lane off Jl. Danau Tamblingan, in central Sanur.'),
    ('kuu-izakaya-dining', 'f7f9dddf24cf360f1bac5473245cc974', 'A Japanese izakaya-style restaurant at Maya Sanur Resort & Spa. The kitchen turns out sushi, sashimi, robatayaki skewers and tempura, and there''s sake and cocktails to drink.'),
    ('la-tribu', 'ac3da059d5a57a7cf4e8cd641d60e797', 'Adults and children both train at this open-air yoga and movement studio on Jl. Buana Sari, Pecatu. Yoga runs from vinyasa, yin, power, kundalini and hatha to surf conditioning, and there''s a 50-hour teacher training. Movement classes cover calisthenics, mobility, contemporary dance and capoeira.'),
    ('la-tribu-bali', '1da71c8abb4846ba66ab1b4f0e34a513', 'A yoga and movement studio near Bingin, on Jl. Buana Sari in Pecatu, that also runs art workshops such as pottery and painting. It teaches handstands and arm balances as well as vinyasa, yin and mobility.'),
    ('leha-leha-spa-sanur', '7eefa0c46dd2a80079d9911b937eb18c', 'Massage and other treatments at local prices, in a neighbourhood day spa near Sanur''s beach path.'),
    ('lilla-pantai', 'e35cf462d10253b5eb50de20e2f2f68f', 'Tables face the sea at this beachfront restaurant on Sanur''s paved coastal walk, at Jalan Duyung. The kitchen cooks Indonesian and European dishes and seafood without MSG, from breakfast to late evening.'),
    ('linga-longa-bar', '45d4afc7919ed460355df93da9d12de7', 'A live-music bar with bands every night, playing rock, pop and Top 40. The main sets start around 8:30pm, late rock sessions run past midnight, and a babi guling (suckling pig) buffet goes on Wednesdays and Sundays.'),
    ('mantra-wellness', '9fcf66c96b502d14d7cab8078cd55b0c', 'A short walk from Padang Padang beach, this wellness centre pairs yoga and pilates with a sauna, cold plunge and mandala pool for recovery. There''s a healthy cafe and coworking too, and the rooms on site are adults-only.'),
    ('marramba-fitness', '5e01ef74e22f4dbbedf64b54dfca5d0d', 'Old-school bodybuilding gym in Renon, close to Sanur. A full set of iron, personal training and clean showers. Upstairs there is a karate section for young people.'),
    ('martha-tilaar-salon-day-spa-sanur', 'd0c33e3bbeca26a08419e9f9dc1a67e7', 'Martha Tilaar''s Sanur branch, where the Indonesian brand does its herbal spa rituals, plus hair, nails and beauty basics.'),
    ('maya-sanur-spa-sanur', 'ae0043b71c8e00ea498ea11ba6118954', 'Maya Sanur Resort & Spa''s beachfront spa has six private double suites in a garden. Certified therapists do traditional massage, body scrubs and facials.'),
    ('maya-sanur-yoga-studio', 'f15175e29033ae5a3ce86a93da164747', 'An air-conditioned, contemporary yoga studio at Maya Sanur Resort & Spa, free for in-house guests at any level. Programmes run from free style and restorative to aqua yoga and sun salutation, with daily sessions also on the beachfront plaza and the rooftop garden.'),
    ('mona-lisa-cafe', '11cd1fd6d0eaa676c04a0fb88e084b43', 'Indonesian staples and international dishes at a casual cafe on Jl. Danau Tamblingan, with vegetarian, vegan and halal options.'),
    ('morning-light-yoga', '8f9682e3cceb8ac0ac4f8af9cd0a3d18', 'A small independent yoga studio on the Bukit that runs scheduled classes. It''s a low-key alternative to Uluwatu''s larger retreat centres.'),
    ('morning-light-yoga-studio', 'c0c1b5bd12775ee35a2c380f6836cd86', 'An open-air shala of reclaimed teak at Uluwatu Surf Villas, on the clifftop above Balangan and the Uluwatu coastline. There is one morning class a day, each day in a different style, with a free coconut afterwards at the Mana cafe.'),
    ('nelayan-restaurant-and-puri-bar', 'fbc55f5c01aa0ad4ac15aaabecbadad1', 'Belmond Jimbaran Puri''s open-air restaurant and bar sit right on the sand of Jimbaran Bay. Nelayan grills seafood and cooks Mediterranean dishes with Indonesian spices and French technique. At Puri Bar, tropical cocktails and local arak come with the sunset across the bay.'),
    ('oranje-bar', 'bc65a20d4756ee120c12ee2ea17ec954', 'A small Dutch-run bar a short walk from Sindhu beach, pouring beer and serving Dutch bar food and snacks.'),
    ('ours-bali-uluwatu-bukit', '94c7d04339b20ab2227f0cbc6237ea13', U&'Ours Bali is an all-day restaurant and bar on the Bukit. Happy hour runs 4\20136pm daily, with discounted cocktails and wines, and you book on the venue''s own website.'),
    ('ours-spa-boutique', '6327f76d16a303c05fd6bf724430287b', 'Dermalogica facials, nails, hair and massage at a neighbourhood day spa on Jalan Labuan Sait, with a sister cafe next door. It works largely with vegan and cruelty-free product lines.'),
    ('piccolina', '664e1d1f9168b489bc4954cbbf472875', 'Hair comes first at this salon on Jl. Labuansait: precision cuts, colour, keratin and blow-dries to European standards. Manicures and massage are available too, and the space doubles as a small wine bottle shop.'),
    ('power-of-now-oasis-sanur', '44d7c7b435b7e936794bbf5f77579d09', 'A yoga and retreat centre in a beachfront shala made of 100% bamboo, on Mertasari beach in south Sanur. Open since 2010 and accredited by Yoga Alliance, it runs daily classes, teacher trainings and holistic treatments, with an organic cafe on site.'),
    ('puri-santrian-spa-sanur', '073ec44a1b1dd3ac8e4f963e46e272cb', 'The spa at Puri Santrian, a family-owned beach resort in south Sanur, has nine double treatment rooms. The menu covers Balinese massage, aromatherapy, reflexology and facials, using Phytomer and Sothys products.'),
    ('puri-santrian-yoga-wellness', '46cb1e0f1bdc79cc46b42bf9be0de9a5', 'Puri Santrian''s resident yoga master leads a free morning beach class of gentle stretching and breathing for in-house guests. The south Sanur resort also has a fitness suite and bicycles. Its spa uses fresh fruit, herbs and plant material alongside Sothys products.'),
    ('raw-gym-uluwatu', '9712c63f36bf08e3756b92f1472d2619', 'Raw Gym''s Uluwatu branch is an open-air warehouse-style gym with a boxing ring and a martial-arts space, on Jalan Raya Uluwatu. Coaches teach Muay Thai, boxing and BJJ alongside strength training, and membership is valid at the other Bali locations too.'),
    ('reform-pilates-bali', '9fa5e584e1755a78ee1495379764fd93', 'A reformer Pilates studio that opened in Bingin in 2023, then added a larger flagship near Suluban Beach with twelve reformers and a rooftop cafe. Group reformer classes run daily, alongside private sessions and duets, and class packs work at both locations.'),
    ('rose-petal', '501a3fc26732404f317a00ca2115d0b5', 'Hair, facials, lashes, brows, nails and body treatments under one roof, at a beauty centre on Jl. Labuansait with a lounge and a sunset terrace. Its colourists are trained in European and Asian techniques such as balayage and lived-in colour.'),
    ('sala-bistro', '8fdadbc59b1a5cb6e3a6a161a5705209', 'Specialty coffee and western-Asian comfort food at a modern bistro on Jl. Danau Tamblingan, with separate brunch and dinner menus.'),
    ('segara-the-seaside', '9b9471a4a253c5c4a2302cc2f4772617', 'A beachfront bar and restaurant right on Sanur''s shore at Jl. Segara Ayu, looking out over the ocean. Seafood, pasta, Indonesian dishes and pizza are on the menu, and there''s a beach happy hour and live music.'),
    ('shankha-spa-and-fitness-at-hyatt-regency-bali', '5b51b4c408e7ec68a7e5f921e897573e', 'The 24-hour gym inside Shankha Spa at Hyatt Regency Bali in Sanur has about 2,000 sq ft of Precor cardio and strength kit. The complex adds ten spa villas around a lily pond, sauna, steam, hot and cold plunge pools and a 15.5-metre lap pool.'),
    ('shankha-spa-hyatt-regency-bali-yoga', '93db21ea9d6a163a6a5187bf2c6cb9e4', 'An open-air yoga studio in the Fitness Pavilion at Shankha Spa, Hyatt Regency Bali in Sanur. It sits in the spa''s garden beside the lap pool, and the schedule has a sunrise class pitched at beginners plus Hatha sessions.'),
    ('six-senses-spa-uluwatu', 'c7c2e85daeb609fa6c5cd0cfe0967c8f', 'Six Senses Uluwatu''s destination spa has treatment rooms, a yoga pavilion and a gym. It uses the Ila product line and locally inspired rituals, and builds bespoke programmes around wellness and biomarker screening.'),
    ('six-senses-uluwatu-fitness-centre', '8afeb9f78b0873be7cc17b67b503a933', 'The resort gym at Six Senses Uluwatu is open 24 hours. Cardio and weight machines join functional training kit, with outdoor circuits on the clifftop grounds. The wellness area around it holds treatment rooms, a relaxation lounge, spa bath, sauna and steam room.'),
    ('six-senses-uluwatu-yoga-pavilion', '4d2f072adbc637ab178f31525470e8c4', 'An air-conditioned yoga pavilion at Six Senses Uluwatu. Daily meditation and an intro-to-yoga session, 30 minutes each, are included for resort guests. Longer 45 to 60 minute sessions, such as Yoga Nidra, traditional yoga and a yogic intestinal cleanse, cost extra.'),
    ('snowcat-bali-ussr-cuisine', 'cca32595ddc8ac31c0f3a52b80ee7454', 'Pelmeni, olivier, draniki and herring under a fur coat come out of this post-Soviet kitchen on Jl. Raya Uluwatu in Ungasan. Portions are large, with homemade infusions to drink. It does delivery as well as dine-in and bookings.'),
    ('soul-on-the-beach', '10596da9e6e2e40e42d64dcb947270e2', 'Breakfast to dinner on Sindhu Beach: this beachfront restaurant next to INNA Sindhu Beach Hotel in Sanur serves Indonesian, Asian and Western food. The white-sand beach is swimmable, and the view runs to Mount Agung and Nusa Penida. Vegetarian and vegan options are available.'),
    ('spa-at-mu', 'b9f4e4ad7aeba234ad4f078551d37db1', 'An open-air cliffside spa at Mu Bali resort that looks over Bingin beach and the Impossibles surf break. Massages are done al fresco with natural and organic oils, facing the ocean and a temple.'),
    ('spring-spa-uluwatu', 'a947f1988a8abedbfa7a8b283caa69e9', 'Treatment rooms, a Davines hair salon and mani-pedi stations make up this day spa on Jalan Labuan Sait. It uses brands such as CODAGE Paris and Davines.'),
    ('studio-fondue', 'ee8c315ae0399f37600a51a14bdf0a47', 'A design-led Pilates studio in Uluwatu that teaches Reformer, Mat and Barre classes. A drop-in class starts from 250K IDR.'),
    ('sudajiva-spa-at-sudamala-sanur-sanur', '3e4dad96faebdd388888c8150e2c7a18', 'Sudajiva Spa ("Water of Life") is the 572 sqm spa at Sudamala Suites & Villas Sanur. It mixes traditional and modern healing techniques in an intimate boutique-resort setting.'),
    ('sudamala-resort-sanur-wellness-yoga-sanur', 'ecdc62c8f6f5fb20a813992b78497655', 'Sudamala Suites & Villas Sanur runs its wellness and yoga programme from a garden Yoga Pavilion, with instructor-led classes and evening meditation. Longer holistic journeys in the Balinese tradition include melukat purification and jamu and boreh workshops.'),
    ('supreme-indian-restaurant', 'fa0abecd9b0cfaf99c020f210e460dc4', 'North and South Indian cooking on Jl. Raya Uluwatu in Ungasan, in an air-conditioned dining room with a bar. Tandoor dishes and curries share the menu with a broad vegetarian and vegan list.'),
    ('svaha-spa-bingin', '36fc691cdccd791affae78d85f9c4a66', 'A cliffside day spa above Bingin with ocean views, doing Balinese massage, scrubs and jacuzzi rituals. Its focus is sustainable and holistic.'),
    ('taru-pramana-spa-sanur', '9cd91bf24a36e35b1f7e04e2f15e1cc1', 'The Meru Sanur''s day spa takes non-guests if they book 24 hours ahead, and it''s open daily from 9am to 9pm. Treatments include Balinese massage, singing-bowl sessions and longer ritual packages.'),
    ('terrace-sanur-the-1o1-bali-oasis-sanur', 'b018796f717e478b98e5abf1339f7428', 'Terrace Sanur is the restaurant of THE 1O1 hotel on Jalan Danau Tamblingan. The hotel is laid out around a lagoon-style pool and landscaped grounds.'),
    ('the-asa-maia', 'a1a1433cf30112b5d05f47c671b23b5f', 'An adults-only wellness retreat in Uluwatu with a small spa, contrast therapy, an infrared sauna and hot and cold plunge pools. It uses local and natural products.'),
    ('the-asa-maia-fitness', '2e7ad38333ab95ade3eb51f34bde1a97', 'The Asa Maia, a family-owned adults-only wellness retreat in Uluwatu opened in 2021, has its gym in the central pavilion. The kit: treadmill, power rack, barbell, kettlebells, dumbbells, slam balls, a stepper, a TRX system and a Pilates Cadillac. An infrared sauna is on site.'),
    ('the-asa-maia-yoga', '35749af8f136d9bc10acf3cbfbd8c9d5', 'Daily yoga at The Asa Maia, in a shala on the top level of the central pavilion. Instructors teach Hatha, Yin and Vinyasa, adapted to each guest''s level. SOMA breathwork is the retreat''s own practice; Indonesian martial arts and Qi Gong are also taught.'),
    ('the-bvlgari-spa', '682e58b81503bbef568b0977fc3bc020', 'Bvlgari Resort Bali''s spa occupies a reconstructed antique Javanese joglo on the Uluwatu cliff, about 150m above the sea, with eight whirlpool treatment rooms. The Royal Lulur couples ritual is on the menu, and treatments can also be done by the beach.'),
    ('the-istana-yoga', 'a7e62e0bd7d2f2b9d44d2f5b8e527e35', 'The Istana''s yoga programme on the Uluwatu cliffs has around 20 class formats, from Vinyasa and Qigong to Rebirthing Breathwork and Yoga Nidra. Instructors are internationally trained, teacher training runs in 200- and 300-hour formats, and drop-ins start from 150,000 IDR.'),
    ('the-space-bali', '74cc5328a4f564e947f4185689095202', 'A community hub in the Bingin and Uluwatu area with two bamboo shalas upstairs and a coworking cafe downstairs. The daily schedule is broad: vinyasa, yin, mobility and surf-mobility classes, plus teacher trainings.'),
    ('the-temple-lodge', '6c47f996933b7ddfbf7eea1ebd0b0840', 'A family-run guesthouse set up for surf and yoga, on the Bingin clifftop above Impossibles and Bingin. Its clifftop shala holds daily yoga that outside guests can join, and the spa and healthy restaurant are on site.'),
    ('the-yoga-rescue', '6b923f8b9157aae968074796a87b241e', 'A quiet garden studio between Ungasan and Jimbaran, away from the busier clifftop crowds. Daily classes cover Hatha, Vinyasa, Ashtanga, Yin and aerial, plus private sessions and workshops.'),
    ('ulu-active-recovery', '6dc93a42141bfbef706ba4b2f398e73c', 'An open-air fitness and recovery centre in Uluwatu, with a cafe. The training side covers strength, HIIT, yoga, Pilates and mobility, in functional training and group classes. The recovery zone has a sauna and steam rooms as well as hot-and-cold plunge pools.'),
    ('ulu-yoga-bali', 'a184f1a20fe670c0747716cee7aa930e', 'A yoga school in a modern, air-conditioned ocean-view shala on Jl. Pantai Cemongkak in Pecatu, a few minutes inland from Bingin and Dreamland. It runs Yoga Alliance 200/300-hour and aerial teacher trainings alongside multi-style drop-in classes.'),
    ('vela-spa', '9c5dd9fb8732b6027ce7dab8320154db', 'An intimate spa at The Ungasan Clifftop Resort, with treatment rooms that look out over the Indian Ocean. Treatments include Balinese massage, scrubs and deep-tissue work.'),
    ('warung-babi-guling-sanur-bypass', 'c0f8f12ead39eab30051cdd4fda6890f', 'Classic Balinese roast pork with rice and trimmings, from a roadside babi guling warung on the Bypass. You can eat in, take away or order delivery.'),
    ('warung-blanjong', '4adc0739cebfe80de1840c7ac73dd518', 'A family-run warung in south Sanur that has been open for around 25 years. The menu centres on nasi campur and Balinese home cooking, with some Indonesian and Western dishes too.'),
    ('warung-coconut-tree', 'ed1ca4ae34dde87ad80a672fdefa0aaa', 'Recycled boat timber makes up the bohemian interior of this Indonesian warung, open since 2012. The plates are generous and home-style Balinese, and there''s live music some evenings.'),
    ('warung-little-bird', 'e461ca898f630ea623a251064f907c77', 'Balinese and Indonesian dishes at budget prices, in a warung on Sanur''s main road, an easy walk from the beach.'),
    ('warung-makan-little-mars', '05a0e3e463f90ace0e4ea04002de4bdb', 'A small, tidy family-run warung with Balinese, Indonesian and some Western dishes, and plenty of vegetarian options. There''s local coffee and fresh cocktails to drink.'),
    ('warung-pregina', 'e38051e90460272ae599ed38fb80f165', 'Duck and roast pork anchor the home-style Balinese cooking at this sit-down warung on the main Danau Tamblingan strip. The room is fitted out in traditional wood.'),
    ('white-orchid-sanur', 'd819e66a6642b729fc4bfaae45fe21af', 'Live music plays in the evenings at this pan-Asian restaurant on Jl. Danau Tamblingan No. 85, where the Asian plates are made for sharing.'),
    ('white-rabbit-lounge-uluwatu-bukit', '68f8d1991939314b4d91d974d552e9e3', 'White Rabbit is a cocktail bar on the Bukit in Uluwatu. The bar says it wants you to feel like you''re drinking with friends, even when you come alone. Booking is on the venue''s own website.'),
    ('yinside-yoga', 'c20370b80c16275f61960a922eb67481', 'Yin Yoga is the focus of this small studio on Jl. Pantai Bingin: classes, workshops, retreats and 50-hour yin teacher trainings. Its shop sells plant-based yoga wear and props, made locally.'),
    ('yoga-searcher-bali', '2deef548641a563bd07f96defebabe16', 'A yoga-centred eco-lodge with recycled-wood villas around a pool, on Jl. Labuan Sait near Padang Padang and Suluban. There''s yoga every day, a plant-forward restaurant and a spa, all set up for retreat-style stays.'),
    ('yoga-the-istana', '6a685b326c56fba5742bcdfd34b30c1d', 'A clifftop yoga studio with ocean views on Jl. Pantai Suluban, home to a resident yoga school and classes led by visiting teachers. Its wellness spa has a sauna, steam and a cold plunge.')
  ) as d(slug, old_md5, val)
  where v.slug = d.slug and v.status = 'active' and v.publication_status = 'published'
    and case when d.old_md5 is null then (v.why_its_here is null or length(trim(v.why_its_here)) = 0) else md5(v.why_its_here) = d.old_md5 end;
  get diagnostics n = row_count; if n <> 89 then raise exception 'wave-uluwatu-sanur-2026-10-08 why_its_here: expected 89 rows, got %', n; end if;

  update venues v set best_for = d.val
